import { Row } from '@tanstack/react-table';
import { Link } from 'react-router-dom';
import { Loan } from '@/types/loan.types';
import { useState } from 'react';
import {
    AlertDialog,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import { apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { toast } from 'sonner';

type ApproveAction = 'direct_approve' | 'forward_to_manager';

export function LoansRequestsActionsCell({ row }: { row: Row<Loan> }) {
    const [approveOpen, setApproveOpen] = useState(false);
    const [approveLoading, setApproveLoading] = useState(false);
    const [rejectOpen, setRejectOpen] = useState(false);
    const [rejectLoading, setRejectLoading] = useState(false);

    const buildBaseBody = () => ({
        loan_type: row.original.loan_type,
        amount: row.original.amount,
        installments: row.original.installments,
        data: row.original.data,
        reason: row.original.reason,
    });

    const submitApproveAction = async (action: ApproveAction) => {
        setApproveLoading(true);
        try {
            const base = buildBaseBody();
            const body =
                action === 'direct_approve'
                    ? { ...base, status: 'approved' as const }
                    : {
                        ...base,
                        status: 'pending_manager' as const,
                        forward_to_responsible_manager: true,
                    };

            await apiPost({
                endpoint: endpoints.loan.update + row.original.id,
                body,
                config: { headers: { 'Content-Type': 'multipart/form-data' } },
            });
            toast.success(
                action === 'direct_approve'
                    ? 'تمت الموافقة على الطلب'
                    : 'تم إرسال الطلب إلى المدير المسؤول للمراجعة',
            );
            setApproveOpen(false);
            row.original.refreshTable?.();
        } catch {
            toast.error('تعذر تنفيذ العملية. حاول مرة أخرى.');
        } finally {
            setApproveLoading(false);
        }
    };

    const submitReject = async () => {
        setRejectLoading(true);
        try {
            await apiPost({
                endpoint: endpoints.loan.update + row.original.id,
                body: { status: 'rejected' as const },
                config: { headers: { 'Content-Type': 'multipart/form-data' } },
            });
            toast.success('تم رفض الطلب');
            setRejectOpen(false);
            row.original.refreshTable?.();
        } catch {
            toast.error('تعذر تنفيذ العملية. حاول مرة أخرى.');
        } finally {
            setRejectLoading(false);
        }
    };

    return (
        <div className="flex flex-row justify-center gap-1">
            <button
                type="button"
                onClick={() => setApproveOpen(true)}
                className="bg-green-success-600 w-14 hover:opacity-85 rounded-lg py-[6px] text-xs font-cairo font-medium border shadow-[0px_1px_2px_0px_#1018280D] text-white-blue-50"
            >
                موافقة
            </button>
            <AlertDialog open={approveOpen} onOpenChange={setApproveOpen}>
                <AlertDialogContent className="font-cairo max-w-md" dir="rtl">
                    <AlertDialogHeader>
                        <AlertDialogTitle className="text-right text-lg font-bold text-primery-blue-500">
                            اختر الإجراء
                        </AlertDialogTitle>
                        <AlertDialogDescription className="text-right text-sm text-[#625E74]">
                            يمكنك الموافقة مباشرة على الطلب، أو إرساله إلى المدير المسؤول لمراجعته قبل الإقرار النهائي.
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <div className="flex flex-col gap-3 py-2">
                        <PrimaryButton
                            type="button"
                            disabled={approveLoading}
                            onClick={() => submitApproveAction('direct_approve')}
                            className="w-full bg-green-success-600 hover:bg-green-success-600/90 py-3 text-sm font-semibold"
                        >
                            {approveLoading ? 'جاري التنفيذ...' : 'تأكيد وأوافق'}
                        </PrimaryButton>
                        <PrimaryButton
                            type="button"
                            disabled={approveLoading}
                            onClick={() => submitApproveAction('forward_to_manager')}
                            className="w-full bg-primery-blue-500 hover:bg-primery-blue-500/90 py-3 text-sm font-semibold"
                        >
                            {approveLoading ? 'جاري التنفيذ...' : 'إرسال للمدير المسؤول'}
                        </PrimaryButton>
                    </div>
                    <AlertDialogFooter className="flex w-full">
                        <AlertDialogCancel asChild>
                            <SecondaryButton type="button" className="w-full">
                                إلغاء
                            </SecondaryButton>
                        </AlertDialogCancel>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
            <button
                type="button"
                onClick={() => setRejectOpen(true)}
                className="bg-red-error-600 w-14 hover:opacity-85 rounded-lg py-[6px] text-xs font-cairo font-medium border shadow-[0px_1px_2px_0px_#1018280D] text-white-blue-50"
            >
                رفض
            </button>
            <AlertDialog open={rejectOpen} onOpenChange={setRejectOpen}>
                <AlertDialogContent className="font-cairo max-w-lg overflow-y-auto">
                    <AlertDialogHeader>
                        <AlertDialogTitle className="text-right text-lg font-bold text-primery-blue-500">
                            تأكيد الرفض
                        </AlertDialogTitle>
                        <AlertDialogDescription className="text-right text-sm text-[#625E74]">
                            هل أنت متأكد من رفض هذا الطلب؟
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter className="flex w-full flex-row-reverse gap-2 sm:justify-start sm:space-x-0">
                        <PrimaryButton
                            type="button"
                            disabled={rejectLoading}
                            onClick={submitReject}
                            className="min-w-[100px] bg-red-error-600 hover:bg-red-error-600/90"
                        >
                            {rejectLoading ? 'جاري التنفيذ...' : 'نعم، رفض'}
                        </PrimaryButton>
                        <AlertDialogCancel asChild>
                            <SecondaryButton type="button" className="min-w-[100px]">
                                إلغاء
                            </SecondaryButton>
                        </AlertDialogCancel>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
            <Link to={`/human-resources/self-services/loan-request-preview/${row.original.id}`}>
                <button className="bg-primery-blue-400 w-14 hover:opacity-85 rounded-lg py-[6px] text-xs font-cairo font-medium border shadow-[0px_1px_2px_0px_#1018280D] text-white-blue-50">
                    معاينة
                </button>
            </Link>
        </div>
    );
}
